refentry.refsect1:
&reftitle.description;
intfalsestream_socket_sendto resourcesocket stringdata intflags0 stringaddress""
Sends the specified data through the socket.

  &reftitle.examples;



    stream_socket_sendto Example


<?php

// Open a server socket on a free port of localhost, and connect to it
$server = stream_socket_server('tcp://127.0.0.1:0');
$socket = stream_socket_client('tcp://' . stream_socket_get_name($server, false));
$peer = stream_socket_accept($server);

// Send ordinary data via ordinary channels
fwrite($socket, 'Normal data transmit.');

// Send one byte of out-of-band data
echo stream_socket_sendto($socket, '!', STREAM_OOB), "\n";

echo "OOB: '" . stream_socket_recvfrom($peer, 10, STREAM_OOB) . "'\n";
echo "Data: '" . stream_socket_recvfrom($peer, 100) . "'\n";

// Close it up
fclose($socket);
fclose($peer);
fclose($server);


    &example.outputs;


1
OOB: '!'
Data: 'Normal data transmit.'
